"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[16353],{84544:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>s,default:()=>c,frontMatter:()=>o,metadata:()=>r,toc:()=>d});var h=n(31085),a=n(71184);const o={sidebar_position:13,slug:"/bible/Daniel/Daniel_13",title:"Daniel 13",hide_table_of_contents:!0},s="Daniel",r={id:"bible/Daniel/Daniel 13",title:"Daniel 13",description:"Chapter 13",source:"@site/docs/bible/Daniel/Daniel 13.md",sourceDirName:"bible/Daniel",slug:"/bible/Daniel/Daniel_13",permalink:"/bibleNotes/docs/bible/Daniel/Daniel_13",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Daniel/Daniel 13.md",tags:[],version:"current",sidebarPosition:13,frontMatter:{sidebar_position:13,slug:"/bible/Daniel/Daniel_13",title:"Daniel 13",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Daniel 12",permalink:"/bibleNotes/docs/bible/Daniel/Daniel_12"},next:{title:"Daniel 14",permalink:"/bibleNotes/docs/bible/Daniel/Daniel_14"}},i={},d=[{value:"Chapter 13",id:"chapter-13",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,a.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"daniel",children:"Daniel"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-13",children:"Chapter 13"}),"\n",(0,h.jsx)(t.p,{children:"The history of Susanna and the two elders. This history of Susanna, in all the ancient Greek and Latin Bibles, was placed in the beginning of the book of Daniel:  till St. Jerome, in his translation, detached it from thence; because he did not find it in the Hebrew:  which is also the case of the history of Bel and the Dragon. But both the one and the other are received by the Catholic Church:  and were from the very beginning a part of the Christian Bible."}),"\n",(0,h.jsx)(n,{verse:1,children:"Now there was a man that dwelt in Babylon, and his name was Joakim:"}),"\n",(0,h.jsx)(n,{verse:2,children:"And he took a wife, whose name was Susanna, the daughter of Helcias, a very beautiful woman, and one that feared God."}),"\n",(0,h.jsx)(n,{verse:3,children:"For her parents being just, had instructed their daughter according to the law of Moses."}),"\n",(0,h.jsx)(n,{verse:4,children:"Now Joakim was very rich, and had an orchard near his house: and the Jews resorted to him, because he was the most honourable of them all."}),"\n",(0,h.jsx)(n,{verse:5,children:"And there were two of the ancients of the people appointed judges that year, of whom the Lord said: That iniquity came out from Babylon, from the ancient judges, that seemed to govern the people."}),"\n",(0,h.jsx)(n,{verse:6,children:"These men frequented the house of Joakim, and all that hand any matters of judgment came to them."}),"\n",(0,h.jsx)(n,{verse:7,children:"And when the people departed away at noon, Susanna went in, and walked in her husband's orchard."}),"\n",(0,h.jsx)(n,{verse:8,children:"And the old men saw her going in every day, and walking: and they were inflamed with lust towards her:"}),"\n",(0,h.jsx)(n,{verse:9,children:"And they perverted their own mind, and turned away their eyes, that they might not look unto heaven, nor remember just judgments."}),"\n",(0,h.jsx)(n,{verse:10,children:"So they were both wounded with the love of her, yet they did not make known their grief one to the other."}),"\n",(0,h.jsx)(n,{verse:11,children:"For they were ashamed to declare to one another their lust, being desirous to have to do with her:"}),"\n",(0,h.jsx)(n,{verse:12,children:"And they watched carefully every day to see her. And one said to the other:"}),"\n",(0,h.jsx)(n,{verse:13,children:"Let us now go home, for it is dinner time. So going out, they departed one from another."}),"\n",(0,h.jsx)(n,{verse:14,children:"And turning back again, they came both to the same place: and asking one another the cause, they acknowledged their lust: and then they agreed together upon a time, when they might find her alone."}),"\n",(0,h.jsx)(n,{verse:15,children:"And it fell out, as they watched a fit day, she went in on a time, as yesterday and the day before, with two maids only, and was desirous to wash herself in the orchard: for it was hot weather."}),"\n",(0,h.jsx)(n,{verse:16,children:"And there was nobody there, but the two old men that had hid themselves, and were beholding her."}),"\n",(0,h.jsx)(n,{verse:17,children:"So she said to the maids: Bring me oil, and washing balls, and shut the doors of the orchard, that I may wash me."}),"\n",(0,h.jsx)(n,{verse:18,children:"And they did as she bade them: and they shut the doors of the orchard, and went out by a back door to fetch what she had commanded them, and they knew not that the elders were hid within."}),"\n",(0,h.jsx)(n,{verse:19,children:"Now when the maids were gone forth, the two elders arose, and ran to her, and said:"}),"\n",(0,h.jsx)(n,{verse:20,children:"Behold the doors of the orchard are shut, and nobody seeth us, and we are in love with thee: wherefore consent to us, and lie with us."}),"\n",(0,h.jsx)(n,{verse:21,children:"But if thou wilt not, we will bear witness against thee, that a young man was with thee, and therefore thou didst send away thy maids form thee."}),"\n",(0,h.jsx)(n,{verse:22,children:"Susanna sighed, and said: I am straitened on every side: for if I do this thing, it is death to me: and if I do it not, I shall not escape your hands."}),"\n",(0,h.jsx)(n,{verse:23,children:"But it is better for me to fall into your hands without doing it, than to sin in the sight of the Lord."}),"\n",(0,h.jsx)(n,{verse:24,children:"With that Susanna cried out with a loud voice: and the elders also cried out against her."}),"\n",(0,h.jsx)(n,{verse:25,children:"And one of them ran to the door of the orchard, and opened it."}),"\n",(0,h.jsx)(n,{verse:26,children:"So when the servants of the house heard the cry in the orchard, they rushed in by the back door, to see what was the matter."}),"\n",(0,h.jsx)(n,{verse:27,children:"But after the old men had spoken, the servants were greatly ashamed: for never had there been any such word said of Susanna. And on the next day,"}),"\n",(0,h.jsx)(n,{verse:28,children:"When the people were come to Joakim, her husband, the two elders also came full of wicked device against Susanna, to put her to death."}),"\n",(0,h.jsx)(n,{verse:29,children:"And they said before the people: Send to Susanna, daughter of Helcias, the wife of Joakim. And presently they sent."}),"\n",(0,h.jsx)(n,{verse:30,children:"And she came with her parents, and children and all her kindred."}),"\n",(0,h.jsx)(n,{verse:31,children:"Now Susanna was exceeding delicate, and beautiful to behold."}),"\n",(0,h.jsx)(n,{verse:32,children:"But those wicked men commanded that her face should be uncovered, (for she was covered) that so at least they might be satisfied with her beauty."}),"\n",(0,h.jsx)(n,{verse:33,children:"Therefore her friends, and all her acquaintance wept."}),"\n",(0,h.jsx)(n,{verse:34,children:"But the two elders rising up in the midst of the people, laid their hands upon her head."}),"\n",(0,h.jsx)(n,{verse:35,children:"And she weeping, looked up to heaven, for her heart had confidence in the Lord."}),"\n",(0,h.jsx)(n,{verse:36,children:"And the elders said: As we walked in the orchard alone, this woman came in with two maids, and shut the doors of the orchard, ans sent away the maids from her."}),"\n",(0,h.jsx)(n,{verse:37,children:"Then a young man that was there hid came to her, and lay with her."}),"\n",(0,h.jsx)(n,{verse:38,children:"But we that were in a corner of the orchard, seeing this wickedness, ran up to them, and we saw them lie together."}),"\n",(0,h.jsx)(n,{verse:39,children:"And him indeed we could not take, because he was stronger than us, and opening the doors, he leaped out:"}),"\n",(0,h.jsx)(n,{verse:40,children:"But having taken this woman, we asked who the young man was, but she would not tell us: of this thing we are witnesses."}),"\n",(0,h.jsx)(n,{verse:41,children:"The multitude believed them, as being the elders, and the judges of the people, and they condemned her to death."}),"\n",(0,h.jsx)(n,{verse:42,children:"Then Susanna cried out with a loud voice, and said: O eternal God, who knowest hidden things, who knowest all things before they come to pass,"}),"\n",(0,h.jsx)(n,{verse:43,children:"Thou knowest that they have borne false witness against me: and behold I must die, whereas I have done none of these things, which these men have maliciously forged against me."}),"\n",(0,h.jsx)(n,{verse:44,children:"And the Lord heard her voice."}),"\n",(0,h.jsx)(n,{verse:45,children:"And when she was led to be put to death, the Lord raised up the holy spirit of a young boy, whose name was Daniel:"}),"\n",(0,h.jsx)(n,{verse:46,children:"And he cried out with a loud voice: I am clear from the blood of this woman."}),"\n",(0,h.jsx)(n,{verse:47,children:"Then all the people turning themselves towards him, said: What meaneth this word that thou hast spoken?"}),"\n",(0,h.jsx)(n,{verse:48,children:"But he standing in the midst of them, said: Are ye so foolish, ye children of Israel, that without examination or knowledge of the truth, you have condemned a daughter of Israel?"}),"\n",(0,h.jsx)(n,{verse:49,children:"Return to judgment, for they have borne false witness against her."}),"\n",(0,h.jsx)(n,{verse:50,children:"So all the people turned again in haste, and the old men said to him: Come, and sit thou down among us, and shew it us: seeing God hath given thee the honour of old age."}),"\n",(0,h.jsx)(n,{verse:51,children:"And Daniel said to the people: Separate these two far from one another, and I will examine them."}),"\n",(0,h.jsx)(n,{verse:52,children:"So when they were put asunder one from the other, he called one of them, and said to him: O thou that art grown old in evil days, now are thy sins come out, which thou hast committed before:"}),"\n",(0,h.jsx)(n,{verse:53,children:"In judging unjust judgments, oppressing the innocent, and letting the guilty to go free, whereas the Lord saith: The innocent and the just thou shalt not kill."}),"\n",(0,h.jsx)(n,{verse:54,children:"Now then if thou sawest her, tell me under what tree thou sawest them conversing together: He said: Under a mastic tree."}),"\n",(0,h.jsx)(n,{verse:55,children:"And Daniel said: Well hast thou lied against thy own head: for behold the angel of God having received the sentence of him, shall cut thee in two."}),"\n",(0,h.jsx)(n,{verse:56,children:"And having put him aside, he commanded that the other should come, and he said to him: O thou seed of Chanaan, and not of Juda, beauty hath deceived tee, and lust hath perverted thy heart:"}),"\n",(0,h.jsx)(n,{verse:57,children:"Thus did you do to the daughters of Israel, and they for fear conversed with you: but a daughter of Juda would not abide your wickedness."}),"\n",(0,h.jsx)(n,{verse:58,children:"Now, therefore, tell me, under what tree didst thou take them conversing together. And he answered: Under a holm tree."}),"\n",(0,h.jsx)(n,{verse:59,children:"And Daniel said to him: Well hast thou also lied against thy own head: for the angel of the Lord waiteth with a sword to cut thee in two, and to destroy you."}),"\n",(0,h.jsx)(n,{verse:60,children:"With that all the assembly cried out with a loud voice, and they blessed God, who saveth them that trust in him."}),"\n",(0,h.jsx)(n,{verse:61,children:"And they rose up against the two elders, (for Daniel had convicted them of false witness by their own mouth) and they did to them as they had maliciously dealt against their neighbour,"}),"\n",(0,h.jsx)(n,{verse:62,children:"To fulfil the law of Moses: and they put them to death, and innocent blood was saved in that day."}),"\n",(0,h.jsx)(n,{verse:63,children:"But Helcias, and his wife, praised God, for their daughter, Susanna, with Joakim, her husband, and all her kindred, because there was no dishonesty found in her."}),"\n",(0,h.jsx)(n,{verse:64,children:"And Daniel became great in the sight of the people from that day, and thence forward."}),"\n",(0,h.jsx)(n,{verse:65,children:"And king Astyages was gathered to his fathers; and Cyrus, the Persian, received his kingdom."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var h=n(14041);const a={},o=h.createContext(a);function s(e){const t=h.useContext(o);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),h.createElement(o.Provider,{value:t},e.children)}}}]);